/// Called every frame by the host. Draws and returns the pixels.
#[unsafe(no_mangle)]
pub extern "C" fn frame(t_ms: u32) -> *const u8 {
    let (width, height) = *SIZE.lock().unwrap();
    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            // A part of the canvas: compare x with a fraction of the width.
            let colour: [u8; 3] = if x < width / 2 { [255, 0, 0] } else { [255, 128, 0] };
            pixels[i..i + 3].copy_from_slice(&colour);
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}

